console.log("[DEBUG] Computing inverse diff...");
const inverseDiff = inverseKitDiff(kitBefore, diff);
console.log("[DEBUG] Inverse diff computed. Keys:", Object.keys(inverseDiff));

// ============================================================
// VERIFY ROUNDTRIP
// ============================================================
console.log("[DEBUG] Verifying forward apply...");
const appliedForward = applyKitDiff(kitBefore, diff);
const forwardOk = areKitsEqual(appliedForward, kitAfter);
console.log("[DEBUG] Forward apply match:", forwardOk);

console.log("[DEBUG] Verifying inverse apply...");
const appliedInverse = applyKitDiff(kitAfter, inverseDiff);
const inverseOk = areKitsEqual(appliedInverse, kitBefore);
console.log("[DEBUG] Inverse apply match:", inverseOk);

console.log("[DEBUG] Verifying diff roundtrip...");
const recomputedDiff = getKitDiff(kitBefore, appliedForward);
const diffRoundtripOk = areKitDiffsEqual(recomputedDiff, diff);
console.log("[DEBUG] Diff roundtrip match:", diffRoundtripOk);

const recomputedInverse = inverseKitDiff(kitBefore, diff);
const inverseRoundtripOk = areKitDiffsEqual(recomputedInverse, inverseDiff);
console.log("[DEBUG] Inverse roundtrip match:", inverseRoundtripOk);

if (!forwardOk || !inverseOk || !diffRoundtripOk || !inverseRoundtripOk) {
  console.error("[DEBUG] VERIFICATION FAILED!");
  if (!forwardOk) {
    console.log("[DEBUG] Forward mismatch - investigating...");
    const fwdJson = JSON.stringify(appliedForward, null, 2);
    const afterJson = JSON.stringify(kitAfter, null, 2);
    if (fwdJson !== afterJson) {
      // Find first difference
      for (let i = 0; i < Math.min(fwdJson.length, afterJson.length); i++) {
        if (fwdJson[i] !== afterJson[i]) {
          console.log("[DEBUG] First diff at char", i);
          console.log("[DEBUG] Applied:", fwdJson.substring(Math.max(0, i - 50), i + 100));
          console.log("[DEBUG] Expected:", afterJson.substring(Math.max(0, i - 50), i + 100));
          break;
        }
      }
    }
  }
  if (!inverseOk) {
    console.log("[DEBUG] Inverse mismatch - investigating...");
    const invJson = JSON.stringify(appliedInverse, null, 2);
    const beforeJson = JSON.stringify(kitBefore, null, 2);
    if (invJson !== beforeJson) {
      for (let i = 0; i < Math.min(invJson.length, beforeJson.length); i++) {
        if (invJson[i] !== beforeJson[i]) {
