    const fwdJson = JSON.stringify(appliedForward, null, 2);
    const afterJson = JSON.stringify(kitAfter, null, 2);
    if (fwdJson !== afterJson) {
      // Find first difference
      for (let i = 0; i < Math.min(fwdJson.length, afterJson.length); i++) {
        if (fwdJson[i] !== afterJson[i]) {
          console.log("[DEBUG] First diff at char", i);
          console.log("[DEBUG] Applied:", fwdJson.substring(Math.max(0, i - 50), i + 100));
          console.log("[DEBUG] Expected:", afterJson.substring(Math.max(0, i - 50), i + 100));
          break;
        }
      }
    }
  }
  if (!inverseOk) {
    console.log("[DEBUG] Inverse mismatch - investigating...");
    const invJson = JSON.stringify(appliedInverse, null, 2);
    const beforeJson = JSON.stringify(kitBefore, null, 2);
    if (invJson !== beforeJson) {
      for (let i = 0; i < Math.min(invJson.length, beforeJson.length); i++) {
        if (invJson[i] !== beforeJson[i]) {
          console.log("[DEBUG] First diff at char", i);
          console.log("[DEBUG] Applied:", invJson.substring(Math.max(0, i - 50), i + 100));
          console.log("[DEBUG] Expected:", beforeJson.substring(Math.max(0, i - 50), i + 100));
          break;
        }
      }
    }
  }
  process.exit(1);
}

