import { readFileSync } from "fs";
import { getKitDiff, applyKitDiff, areKitsEqual, Kit, Type, areTypesEqual } from "/workspaces/semio/semio/js/semio";

const kitRaw: Kit = JSON.parse(readFileSync("/workspaces/semio/semio/assets/semio/kit_metabolism.json", "utf-8"));
const kitBefore: Kit = { ...kitRaw, designs: (kitRaw.designs ?? []).filter((d: any) => !d.parent) };

// Test updating a connector point
const kitAfter: Kit = JSON.parse(JSON.stringify(kitBefore));
const baseType = kitAfter.types!.find((t: any) => t.guid === "277768b5-9220-4312-bf0d-ab82d9fb6a73") as any;
baseType.connectors[0].point = { x: 10, y: 20, z: 30 };
const diff = getKitDiff(kitBefore, kitAfter);
const applied = applyKitDiff(kitBefore, diff);

// Compare type by type
for (const typeA of applied.types!) {
  const typeB = kitAfter.types!.find((t: any) => t.guid === typeA.guid) as any;
  if (!typeB) {
    console.log("[DEBUG] Missing type:", typeA.guid, (typeA as any).name);
    continue;
  }
  // Check each field
  if (typeA.name !== typeB.name) console.log("[DEBUG] name diff:", typeA.guid, typeA.name, "vs", typeB.name);
  if (typeA.description !== typeB.description) console.log("[DEBUG] desc diff:", typeA.guid);
  // Compare connectors
  const connsA = typeA.connectors ?? [];
  const connsB = typeB.connectors ?? [];
  if (connsA.length !== connsB.length) {
    console.log("[DEBUG] conns length:", typeA.guid, connsA.length, "vs", connsB.length);
    continue;
  }
  for (const connA of connsA) {
    const connB = connsB.find((c: any) => c.guid === connA.guid);
    if (!connB) {
      console.log("[DEBUG] missing conn:", connA.guid, "in type", typeA.guid);
      continue;
    }
    if (connA.point.x !== connB.point.x || connA.point.y !== connB.point.y || connA.point.z !== connB.point.z) {
      console.log("[DEBUG] point diff:", connA.guid, JSON.stringify(connA.point), "vs", JSON.stringify(connB.point));
    }
    if (connA.direction.x !== connB.direction.x || connA.direction.y !== connB.direction.y || connA.direction.z !== connB.direction.z) {
      console.log("[DEBUG] dir diff:", connA.guid, JSON.stringify(connA.direction), "vs", JSON.stringify(connB.direction));
    }
  }
}

// Also check scalar kit fields
console.log("[DEBUG] kit name:", applied.name, "vs", kitAfter.name, applied.name === kitAfter.name);
console.log("[DEBUG] kit version:", applied.version, "vs", kitAfter.version, applied.version === kitAfter.version);

// Check types count
console.log("[DEBUG] types count:", applied.types!.length, "vs", kitAfter.types!.length);

// Full comparison with manual exclusion
let mismatchFound = false;
for (const typeA of applied.types!) {
  const typeB = kitAfter.types!.find((t: any) => t.guid === typeA.guid);
  if (!typeB) { console.log("[DEBUG] MISSING TYPE IN AFTER:", typeA.guid); mismatchFound = true; continue; }
  if (JSON.stringify(typeA) !== JSON.stringify(typeB)) {
    // Find which key is different
    const keysA = Object.keys(typeA as any);
    const keysB = Object.keys(typeB as any);
    for (const key of new Set([...keysA, ...keysB])) {
      if (JSON.stringify((typeA as any)[key]) !== JSON.stringify((typeB as any)[key])) {
        console.log("[DEBUG] TYPE", typeA.guid, "KEY", key, "DIFF");
        console.log("[DEBUG]   A:", JSON.stringify((typeA as any)[key]).substring(0, 200));
        console.log("[DEBUG]   B:", JSON.stringify((typeB as any)[key]).substring(0, 200));
        mismatchFound = true;
      }
    }
  }
}
if (!mismatchFound) console.log("[DEBUG] All types match in JSON!");
