import { readFileSync } from "fs";
import { getKitDiff, inverseKitDiff, applyKitDiff, areKitsEqual, areDesignsEqual, Kit } from "/workspaces/semio/semio/js/semio";

const ASSETS_DIR = "/workspaces/semio/semio/assets/semio";
const kitRaw: Kit = JSON.parse(readFileSync(`${ASSETS_DIR}/kit_metabolism.json`, "utf-8"));
const kitBefore: Kit = { ...kitRaw, designs: (kitRaw.designs ?? []).filter((d: any) => !d.parent) };

const kitAfter: Kit = JSON.parse(JSON.stringify(kitBefore));
const d = kitAfter.designs!.find((d: any) => d.guid === "37ba7ec4-9023-4be7-9ab6-e0ebc80007f8") as any;
console.log("[DEBUG] connection count:", d.connections?.length);
console.log("[DEBUG] connection 0:", JSON.stringify(d.connections?.[0], null, 2));

d.connections[0].gap = 100;
d.connections[0].description = "modified connection";

const diff = getKitDiff(kitBefore, kitAfter);
const inv = inverseKitDiff(kitBefore, diff);
console.log("[DEBUG] diff designs:", JSON.stringify(diff.designs, null, 2).substring(0, 2000));
console.log("[DEBUG] inv designs:", JSON.stringify(inv.designs, null, 2).substring(0, 2000));

const appliedFwd = applyKitDiff(kitBefore, diff);
const appliedInv = applyKitDiff(kitAfter, inv);

// Compare design by design
const origDesign = kitBefore.designs!.find((d: any) => d.guid === "37ba7ec4-9023-4be7-9ab6-e0ebc80007f8")!;
const invDesign = appliedInv.designs!.find((d: any) => d.guid === "37ba7ec4-9023-4be7-9ab6-e0ebc80007f8")!;

console.log("[DEBUG] areDesignsEqual:", areDesignsEqual(origDesign, invDesign));

// Check connection-by-connection
const origConn = (origDesign as any).connections?.[0];
const invConn = (invDesign as any).connections?.[0];
console.log("[DEBUG] orig conn 0 gap:", origConn?.gap, "desc:", origConn?.description);
console.log("[DEBUG] inv conn 0 gap:", invConn?.gap, "desc:", invConn?.description);

// Check if connections count matches
console.log("[DEBUG] orig connections:", (origDesign as any).connections?.length);
console.log("[DEBUG] inv connections:", (invDesign as any).connections?.length);

// Check all design fields
for (const key of new Set([...Object.keys(origDesign), ...Object.keys(invDesign)])) {
  const origVal = (origDesign as any)[key];
  const invVal = (invDesign as any)[key];
  if (JSON.stringify(origVal) !== JSON.stringify(invVal)) {
    console.log(`[DEBUG] DIFF on field "${key}":`);
    if (typeof origVal === 'object') {
      console.log(`  orig length: ${Array.isArray(origVal) ? origVal?.length : 'N/A'}`);
      console.log(`  inv length: ${Array.isArray(invVal) ? invVal?.length : 'N/A'}`);
    } else {
      console.log(`  orig: ${origVal}`);
      console.log(`  inv: ${invVal}`);
    }
  }
}
ENDOFSCRIPT
