const origDesign = kitBefore.designs!.find((d: any) => d.guid === "37ba7ec4-9023-4be7-9ab6-e0ebc80007f8") as any;
const invDesign = appliedInv.designs!.find((d: any) => d.guid === "37ba7ec4-9023-4be7-9ab6-e0ebc80007f8") as any;

// Compare connections
const connGuid = "c18d2e83-0821-4ab7-9547-494021854fc1";
