console.log("[DEBUG] areConnectionsEqual:", areConnectionsEqual(origConn, invConn));

for (const key of new Set([...Object.keys(origConn), ...Object.keys(invConn)])) {
  const o = origConn[key];
  const i = invConn[key];
  if (JSON.stringify(o) !== JSON.stringify(i)) {
    console.log(`[DEBUG] DIFF "${key}": orig=${JSON.stringify(o)} inv=${JSON.stringify(i)}`);
  }
}

// Also check connection count 
console.log("[DEBUG] orig connections:", origDesign.connections.length, "inv connections:", invDesign.connections.length);

// Check all connections equality
let allEqual = true;
for (const oc of origDesign.connections) {
  const ic = invDesign.connections.find((c: any) => c.guid === oc.guid);
  if (!ic) { console.log(`[DEBUG] Missing conn: ${oc.guid}`); allEqual = false; continue; }
  if (!areConnectionsEqual(oc, ic)) {
    console.log(`[DEBUG] Unequal conn: ${oc.guid}`);
    for (const key of new Set([...Object.keys(oc), ...Object.keys(ic)])) {
      if (JSON.stringify(oc[key]) !== JSON.stringify(ic[key])) {
        console.log(`  "${key}": ${JSON.stringify(oc[key])} vs ${JSON.stringify(ic[key])}`);
      }
    }
    allEqual = false;
  }
}
console.log("[DEBUG] All connections equal:", allEqual);
