  typeToUpdate.location = { guid: newGuid() }; // LocationIdSchema = {guid}
  typeToUpdate.icon = "updated-base-icon.svg";
  typeToUpdate.image = "updated-base-image.png";
  typeToUpdate.authors = [{ guid: kitBefore.authors![0].guid }];
  typeToUpdate.concepts = [{ guid: kitBefore.concepts![0].guid }];
  typeToUpdate.parent = { guid: types.find((t: any) => t.guid === "4ca3b87b-cd76-4228-9f7e-1459b711f0ab")!.guid };

  // MODELS nested: remove 1, update 1, add 1
  const modelsToRemoveIdx = typeToUpdate.models.findIndex(
