import { readFileSync } from "fs";
import { getKitDiff, inverseKitDiff, applyKitDiff, areKitsEqual, Kit } from "/workspaces/semio/semio/js/semio";

const ASSETS_DIR = "/workspaces/semio/semio/assets/semio";
const kitRaw: Kit = JSON.parse(readFileSync(`${ASSETS_DIR}/kit_metabolism.json`, "utf-8"));
const kitBefore: Kit = { ...kitRaw, designs: (kitRaw.designs ?? []).filter((d: any) => !d.parent) };

function test(name: string, modify: (k: Kit) => void) {
  const kitAfter: Kit = JSON.parse(JSON.stringify(kitBefore));
  modify(kitAfter);
  const diff = getKitDiff(kitBefore, kitAfter);
  const applied = applyKitDiff(kitBefore, diff);
  const fwd = areKitsEqual(applied, kitAfter);
  const inv = inverseKitDiff(kitBefore, diff);
  const invApplied = applyKitDiff(kitAfter, inv);
  const invOk = areKitsEqual(invApplied, kitBefore);
  console.log(`[DEBUG] ${name}: fwd=${fwd} inv=${invOk}`);
  if (!invOk) {
    // Compare the specific design
    const origD = kitBefore.designs!.find((d: any) => d.guid === "37ba7ec4-9023-4be7-9ab6-e0ebc80007f8") as any;
    const invD = invApplied.designs!.find((d: any) => d.guid === "37ba7ec4-9023-4be7-9ab6-e0ebc80007f8") as any;
    // Check piece 0
    const origP = origD.pieces[0];
    const invP = invD.pieces.find((p: any) => p.guid === origP.guid);
    if (invP) {
      for (const key of new Set([...Object.keys(origP), ...Object.keys(invP)])) {
        if (JSON.stringify(origP[key]) !== JSON.stringify(invP[key])) {
          console.log(`[DEBUG]   piece field "${key}": orig=${JSON.stringify(origP[key])} inv=${JSON.stringify(invP[key])}`);
        }
      }
    } else {
      console.log("[DEBUG]   piece not found in inverted!");
    }
  }
}

